CREATE TABLE organizations(id varchar(40) PRIMARY KEY, name varchar(200) NOT NULL);
CREATE TABLE access_grant(username varchar(200) PRIMARY KEY, roles varchar(500) NOT NULL, orgs varchar(500) NOT NULL, enabled boolean NOT NULL DEFAULT true);
CREATE TABLE master(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL REFERENCES organizations, kind varchar(40) NOT NULL, name varchar(200) NOT NULL, data text NOT NULL, active boolean NOT NULL DEFAULT true, version integer NOT NULL DEFAULT 0, UNIQUE(org,kind,name));
CREATE TABLE document(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL REFERENCES organizations, kind varchar(40) NOT NULL, number varchar(100) NOT NULL, doc_date date NOT NULL, state varchar(30) NOT NULL, creator varchar(200) NOT NULL, source_id varchar(40), payload text NOT NULL, total numeric(20,2) NOT NULL, net numeric(20,2) NOT NULL, cost numeric(20,2) NOT NULL DEFAULT 0, currency varchar(3) NOT NULL, rate numeric(20,6) NOT NULL, version integer NOT NULL DEFAULT 0, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(org,kind,number));
CREATE INDEX document_filter ON document(org,kind,doc_date,state);
CREATE TABLE stock(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL REFERENCES organizations, warehouse varchar(40) NOT NULL, item varchar(40) NOT NULL, serial varchar(200) NOT NULL, qty numeric(20,3) NOT NULL CHECK(qty>=0), value numeric(20,2) NOT NULL CHECK(value>=0), employee varchar(40), UNIQUE(org,warehouse,item,serial));
CREATE TABLE movement(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, document_id varchar(40) NOT NULL REFERENCES document, doc_date date NOT NULL, warehouse varchar(40) NOT NULL, item varchar(40) NOT NULL, serial varchar(200) NOT NULL, qty numeric(20,3) NOT NULL, value numeric(20,2) NOT NULL);
CREATE INDEX movement_history ON movement(org,doc_date,item);
CREATE TABLE reservation(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, document_id varchar(40) NOT NULL REFERENCES document, stock_id varchar(40) NOT NULL REFERENCES stock, qty numeric(20,3) NOT NULL CHECK(qty>0));
CREATE TABLE payment(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, document_id varchar(40) NOT NULL REFERENCES document, amount numeric(20,2) NOT NULL CHECK(amount>0), paid_on date NOT NULL, idem varchar(100) NOT NULL, UNIQUE(org,idem));
CREATE TABLE employee(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, code varchar(80) NOT NULL UNIQUE, name varchar(200) NOT NULL, username varchar(200), state varchar(30) NOT NULL DEFAULT 'INCOMPLETE', hired_on date, fired_on date, data text NOT NULL, version integer NOT NULL DEFAULT 0);
CREATE TABLE hr_event(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, employee_id varchar(40) NOT NULL REFERENCES employee, kind varchar(40) NOT NULL, event_date date NOT NULL, data text NOT NULL);
CREATE TABLE absence(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, employee_id varchar(40) NOT NULL REFERENCES employee, kind varchar(40) NOT NULL, starts date NOT NULL, ends date NOT NULL, state varchar(30) NOT NULL, comment text NOT NULL);
CREATE TABLE timesheet(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, month varchar(7) NOT NULL, data text NOT NULL, closed boolean NOT NULL DEFAULT false, UNIQUE(org,month));
CREATE TABLE periods(org varchar(40) NOT NULL, until_date date NOT NULL, PRIMARY KEY(org));
CREATE TABLE comment(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, document_id varchar(40) NOT NULL REFERENCES document, author varchar(200) NOT NULL, body text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE attachment(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, document_id varchar(40) NOT NULL REFERENCES document, name varchar(255) NOT NULL, size_bytes bigint NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE audit(id varchar(40) PRIMARY KEY, org varchar(40), actor varchar(200) NOT NULL, action varchar(100) NOT NULL, object_id varchar(100) NOT NULL, detail text NOT NULL, request_id varchar(100) NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE outbox(id varchar(40) PRIMARY KEY, org varchar(40) NOT NULL, topic varchar(100) NOT NULL, payload text NOT NULL, created_at timestamp with time zone NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE idempotency(org varchar(40) NOT NULL, actor varchar(200) NOT NULL, idem varchar(100) NOT NULL, fingerprint varchar(64) NOT NULL, result_id varchar(40) NOT NULL, PRIMARY KEY(org,actor,idem));
